document.addEventListener("DOMContentLoaded",(()=>{SnapSelect(".snapSelect",{liveSearch:!0,placeholder:"Select Post Types...",clearAllButton:!0,closeOnSelect:!1,allowEmpty:!0});let e=document.getElementById("cfo-purge-container").children;for(const n of e)n.onclick=function(){t(n.dataset.cfoMarket)};async function t(e){try{const t=await fetch("/wp-json/cfo/purge_market?"+new URLSearchParams({market_id:e}).toString(),{headers:{"X-WP-Nonce":myUserData.nonce},credentials:"same-origin"});if(!t.ok)throw new Error(`Response status: ${t.status}`);const n=await t.text();0!==n.length&&console.log(n.length)}catch(e){console.error(e)}}}));